import { Link } from "react-router-dom";

type AuthInlineAlertVariant = "error" | "info" | "success";

const AUTH_INLINE_ALERT_VARIANT_CLASS_MAP: Record<AuthInlineAlertVariant, string> = {
    error:
        "border-[var(--color-feedback-error)] bg-[var(--color-danger-soft)] text-brand",
    info:
        "border-[var(--color-accent)] bg-[rgba(12,174,154,0.12)] text-brand",
    success:
        "border-[var(--color-accent)] bg-[rgba(12,174,154,0.12)] text-brand",
};

export function AuthInlineAlert({
    message,
    variant = "error",
}: {
    message: string;
    variant?: AuthInlineAlertVariant;
}) {
    return (
        <div
            role="alert"
            aria-live="polite"
            className={`rounded-[12px] border px-[14px] py-[12px] text-[12px] font-[400] tracking-[-0.48px] ${AUTH_INLINE_ALERT_VARIANT_CLASS_MAP[variant]}`}
        >
            {message}
        </div>
    );
}

