export function AuthDivider() {
    return (
        <div className="mb-[16px] mt-[16px] flex w-full flex-row items-center gap-2">
            <div className="h-px min-w-0 flex-1 bg-brand-border" aria-hidden />
            <span className="shrink-0 text-[12px] font-[400] tracking-[-0.48px] text-brand-border">
                or
            </span>
            <div className="h-px min-w-0 flex-1 bg-brand-border" aria-hidden />
        </div>
    );
}

export function AuthCloseLink() {
    return (
        <Link to="/">
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 14 14" fill="none" className="text-brand">
                <path d="M1 1L12.3137 12.3137" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                <path d="M12.3125 1L0.998791 12.3137" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
            </svg>
        </Link>
    );
}
